    def run_schedule_for_update_server_data(self):
        """
        run schedule for update server data
        """

        schedule.every(update_server_time).seconds.do(self.update_server_data)
        schedule.every(update_db_time).seconds.do(self.update_db_data)
        logging.info('run schedule for update server data')
        while True:
            schedule.run_pending()
            time.sleep(1)



    def update_db_data(self):
        """ save records in local db """
        if not self.user_id:
            return
        db_i.update_records_in_db(self.records, self.user_id)


    def update_server_data(self):
        """ update server records with local db records"""
        if not self.user_id:
            return
        db_records = db_i.get_records(self.user_id)
        if not db_records:
            return True 
        try:
            url = host_url+"/api/update-records/"
            headers = {"Authorization": "Bearer"+" "+self.access_token}
            logging.info('update server data')
            data = {'records': json.dumps(db_records, default=str)}
            r = requests.post(url, data =data , headers = headers, verify=False)
            if r.status_code == 401:
                messagebox.showerror("خطا", "شما از اکانت خود خارج شده اید. برای حل مشکل باید دیتابیس خود را پاک کرده و دوباره وارد شوید.")
                print("Unauthorized request. Status code 401.")
                return True 

            res = r.json()
            if 'success' in res and res['success']:
                db_i.mark_updated_records_as_sent(res['updated_ids'])
            else:
                messagebox.showerror("خطا", "خطایی هنگام بروزرسانی سرور رخ داده است. برای رفع خطا به مدیر سیستم اطلاع دهید.")
        except Exception as e:
            err = 'update server error : '+str(e)
            logging.error(err)
            

    def initialize_recording_variables(self):
        """
        initialize variables for recording from server or db
        """
        try:
            url = host_url+"/api/initialize-record-variables/"
            headers = {"Authorization": "Bearer"+" "+self.access_token}
            r = requests.get(url, data = {}, headers = headers, verify=False)
            res = r.json()
            logging.info('intialize variablees from server')
            if 'success' in res and res['success']:
                self.allowed_inactive_time = int(res['allowed_inactive_time']) * 60
                self.record_apps = [d['name']for d in res['apps'] if not d['is_browser']]
                self.browser_apps = [d['name'] for d in res['apps'] if d['is_browser'] ]
                self.record_domains = [d['domain'] for d in res['websites'] ]
                self.record_not_domains = [d['domain'] for d in res['websites'] if '/' in d['domain'] ]
                self.user_id = res['user_id']
                db_i.update_db_intializes(res) 
            else:
                # need to load from local database
                db_i.initialize_variables_from_db(self)
        except Exception as e:
            err = 'intialize from server error : '+str(e)
            logging.error(err)
            # need to load from local database
            db_i.initialize_variables_from_db(self)



    def logintolomin(self):     
        """
        login actions
        """
        user = self.Username.get()
        passw = self.password.get()
        try:
            token_url = host_url+"/api/token/"
            data = {'username': user , 'password': passw}
            r = requests.post(token_url, json = data, verify=False)
            res = r.json()
            logging.info('try to login')
            if 'access' not in res:
                messagebox.showinfo(message='نام کاربری یا رمز عبور اشتباه است')
                return 
            waiting = False
            refresh = res['refresh']   
            refresh_url = host_url+"/api/token/refresh/"
            data = {'refresh': refresh}
            r = requests.post(refresh_url, json = data, verify=False)
            res = r.json()
            
            access_token = res['access']
        except Exception as e:
            err = 'login error : '+ str(e)
            logging.error(err)
            messagebox.showinfo(message='خطایی در اتصال به سرور پیش آمده است.')
            return 
            
        self.access_token = access_token
        self.initialize_recording_variables()
        db_i.save_user_access_token(self.user_id,access_token)
        self.record_page()


