    def stop_recording(self):
        logging.info('stop recording')
        self.last_record['end'] = datetime.datetime.now()
        self.is_recording = False
        self.record_page()
        self.update_db_data()
        self.update_server_data() 



    def start_recording(self):
        """
        load is recording page
        """

        if db_i.record_without_end_exists(self.user_id):
            messagebox.showinfo(message='شما یک کار بدون پایان دارید. لطفا از طریق سایت برای آن پایان ثبت کنید.')
            return 
        for i in self.master.winfo_children():
            i.destroy()
        
        self.last_record = {'start':datetime.datetime.now(),'end':None,'last_updated':datetime.datetime.now(),'sum_words':0,'logs':[],
            'sum_inactive_time':0,'inactive_times':[],'apps':{},'browser_apps':{}}
        # if self.is_deactive : 
            
        self.records.append(self.last_record)
        for app in self.record_apps :
            self.last_record['apps'][app] = 0

        for app in self.browser_apps:
            self.last_record['browser_apps'][app] = {}
            for domain in self.record_domains:
                    self.last_record['browser_apps'][app][domain] = 0
            for domain in self.record_not_domains:
                    self.last_record['browser_apps'][app][domain] = 0
        now = datetime.datetime.now()
        n_time = 'شروع از ' + str(now.time())[:5]
        self.frame_recording_page = Frame(self.master, width=250, height=75)
        self.frame_recording_page.pack()
        self.time_label = ttk.Label(self.frame_recording_page,text =n_time, font = self.font_b)
        self.time_label.place(x = 110, y = 15)

        inactive_time_str = 'غیر فعال : 0 دقیقه'
        self.inactive_label = ttk.Label(self.frame_recording_page,text =inactive_time_str)
        self.inactive_label.place(x = 110, y = 40)   
        self.stop_record_btn = Button(self.frame_recording_page, text ="پایان", font = self.font_b, fg='#fff',
                            bg ='#407eca', command = self.stop_recording)
        self.stop_record_btn.place(x = 20, y = 15, width = 60)
        self.is_recording = True
        logging.info('start recording threads')
        root = auto.GetRootControl()
        auto.EnumAndLogControl(root, 1)

        record_thread = threading.Thread(target=self.record_time, args=(root,))
        record_thread.start()

        # record user inactive time
        inactive_thread = threading.Thread(target=self.record_inactive_time, args=())
        inactive_thread.start()
        # monitor user activity
        user_activity_thread = threading.Thread(target=self.user_activity_monitor)
        user_activity_thread.start()

        sum_words_thread = threading.Thread(target=self.record_sum_words, args=())
        sum_words_thread.start()

        msgloop_thread = threading.Thread(target=self.check_shutdown, args=())
        msgloop_thread.start()
        hh_thread = threading.Thread(target=self.handle_next_day_record, args=())
        hh_thread.start()
        
        logging.info('recording threads started successfully')


