    def check_shutdown(self):
        """ Testing Windows shutdown events """
        try:
            hinst = win32api.GetModuleHandle(None)
            wndclass = win32gui.WNDCLASS()
            wndclass.hInstance = hinst
            wndclass.lpszClassName = "testWindowClass"
            messageMap = { win32con.WM_QUERYENDSESSION : self.wndproc,
                        win32con.WM_ENDSESSION : self.wndproc,
                        win32con.WM_QUIT : self.wndproc,
                        win32con.WM_DESTROY : self.wndproc,
                        win32con.WM_CLOSE : self.wndproc }
            
            wndclass.lpfnWndProc = messageMap
            
            try:
                myWindowClass = win32gui.RegisterClass(wndclass)
                hwnd = win32gui.CreateWindowEx(win32con.WS_EX_LEFT,
                                            myWindowClass, 
                                            "testMsgWindow", 
                                            0, 
                                            0, 
                                            0, 
                                            win32con.CW_USEDEFAULT, 
                                            win32con.CW_USEDEFAULT, 
                                            0, 
                                            0, 
                                            hinst, 
                                            None)
                logging.info('hwnd created')
            except Exception as e:
                hwnd = None
                logging.error("hwnd exception: %s" % str(e))

            

            if hwnd is None:
                logging.error("hwnd is none!")
            else:
                logging.info("hwnd: %s" % hwnd)
            
            while self.is_recording :
                win32gui.PumpWaitingMessages()
                time.sleep(1)
        except Exception as e:
            logging.error("check shutdown exception: %s" % str(e))

